package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	var s string
	fmt.Fscan(in, &n)
	fmt.Fscan(in, &s)
	m := len(s)

	// Build KMP automaton for pattern s
	pi := make([]int, m)
	for i := 1; i < m; i++ {
		j := pi[i-1]
		for j > 0 && s[i] != s[j] {
			j = pi[j-1]
		}
		if s[i] == s[j] {
			j++
		}
		pi[i] = j
	}
	// next state for each kmp state and bit
	next := make([][2]int, m+1)
	for state := 0; state <= m; state++ {
		for b := 0; b < 2; b++ {
			if state == m {
				// once matched, stay matched
				next[state][b] = m
				continue
			}
			c := byte('0' + b)
			j := state
			for j > 0 && s[j] != c {
				j = pi[j-1]
			}
			if j < m && s[j] == c {
				j++
			}
			next[state][b] = j
		}
	}

	// DP[pos][kmpState][matched][firstBit] = count
	// pos: 0..n, kmpState:0..m, matched:0/1, firstBit:0/1/2(2 means not set yet)
	dp := make([][][][]int64, n+1)
	for i := 0; i <= n; i++ {
		dp[i] = make([][][]int64, m+1)
		for j := 0; j <= m; j++ {
			dp[i][j] = make([][]int64, 2)
			for k := 0; k < 2; k++ {
				dp[i][j][k] = make([]int64, 3)
			}
		}
	}
	dp[0][0][0][2] = 1

	for pos := 0; pos < n; pos++ {
		for st := 0; st <= m; st++ {
			for matched := 0; matched < 2; matched++ {
				for fb := 0; fb < 3; fb++ {
					cur := dp[pos][st][matched][fb]
					if cur == 0 {
						continue
					}
					for b := 0; b < 2; b++ {
						nfb := fb
						if pos == 0 {
							nfb = b
						}
						nst := next[st][b]
						nmatched := matched
						if nst == m {
							nmatched = 1
						}
						dp[pos+1][nst][nmatched][nfb] += cur
					}
				}
			}
		}
	}

	// Now we must ensure that s appears in some cyclic shift.
	// That is equivalent to s appearing in t+t (length 2n).
	// We already tracked matches in linear t; but we also need matches that wrap.
	// To handle wrap, we simulate continuing KMP over the prefix again.

	// For each completed string t, reconstruct its KMP state sequence over t,
	// then continue over its prefix to see if any match occurs that crosses boundary.
	// Instead of reconstructing, we can simulate all possibilities again but track
	// whether match occurs in positions [n+1..2n] using starting states from end.

	// Enumerate all strings via DP states at pos=n
	var total int64
	// For each final DP state, we know count of strings with that final KMP state and matched flag.
	// For those with matched==1, they already have s in linear t, so they are valid.
	for st := 0; st <= m; st++ {
		for fb := 0; fb < 2; fb++ {
			total += dp[n][st][1][fb]
		}
	}

	// For matched==0, we must check wrap-around.
	// For each final KMP state 'st' and firstBit 'fb', we need to know
	// if continuing KMP over the first n bits can produce a match.
	// But we don't know the actual bits, only aggregated counts.
	// So we need a second DP over prefix with parameter initial state.

	// prefixDP[pos][state][firstBit] = number of strings of length pos with given KMP state and firstBit
	prefixDP := make([][][]int64, n+1)
	for i := 0; i <= n; i++ {
		prefixDP[i] = make([][]int64, m+1)
		for j := 0; j <= m; j++ {
			prefixDP[i][j] = make([]int64, 3)
		}
	}
	prefixDP[0][0][2] = 1
	for pos := 0; pos < n; pos++ {
		for st := 0; st <= m; st++ {
			for fb := 0; fb < 3; fb++ {
				cur := prefixDP[pos][st][fb]
				if cur == 0 {
					continue
				}
				for b := 0; b < 2; b++ {
					nfb := fb
					if pos == 0 {
						nfb = b
					}
					nst := next[st][b]
					prefixDP[pos+1][nst][nfb] += cur
				}
			}
		}
	}

	// Now we need, for each final state st_end and firstBit fb, among all strings counted in dp[n][st_end][0][fb],
	// how many have a match when we continue KMP from st_end over their own prefix.
	// This is equivalent to counting pairs (t) such that:
	// - t leads to state st_end after n steps without match
	// - continuing KMP from st_end over t's prefix yields a match.
	// This is a convolution over automaton paths; direct counting is complex.
	// Given constraints n<=40, we can brute force all 2^n strings.

	total = 0
	limit := int64(1) << uint(n)
	for mask := int64(0); mask < limit; mask++ {
		t := make([]byte, n)
		for i := 0; i < n; i++ {
			if (mask>>uint(i))&1 == 1 {
				t[i] = '1'
			} else {
				t[i] = '0'
			}
		}
		// check if s appears in some cyclic shift: i.e., in t+t
		state := 0
		found := false
		for i := 0; i < 2*n && !found; i++ {
			c := t[i%len(t)]
			j := state
			for j > 0 && (j == m || s[j] != c) {
				j = pi[j-1]
			}
			if j < m && s[j] == c {
				j++
			}
			state = j
			if state == m {
				found = true
			}
		}
		if found {
			total++
		}
	}

	fmt.Println(total)
}

