			j := state
			for j > 0 && s[j] != c {
				j = pi[j-1]
			}
			if j < m && s[j] == c {
				j++
			}
			if j == m {
				nxt[state][b] = m
			} else {
				nxt[state][b] = j
			}
		}
	}

	// DP[pos][state][matched][firstBit]
	// matched: 0/1, firstBit: 0/1 (only meaningful when pos>0)
	dp := make([][][][2]int64, n+1)
	for i := 0; i <= n; i++ {
		dp[i] = make([][][2]int64, m+1)
		for j := 0; j <= m; j++ {
			dp[i][j] = make([][2]int64, 2)
		}
	}

	// initialize position 0: choose first bit
	for b := 0; b < 2; b++ {
		state := nxt[0][b]
		matched := 0
		if state == m {
			matched = 1
		}
		dp[1][state][matched][b]++
	}

	for pos := 1; pos < n; pos++ {
		for state := 0; state <= m; state++ {
			for matched := 0; matched <= 1; matched++ {
				for first := 0; first <= 1; first++ {
					cur := dp[pos][state][matched][first]
					if cur == 0 {
						continue
					}
					for b := 0; b < 2; b++ {
						ns := nxt[state][b]
						nm := matched
						if ns == m {
							nm = 1
						}
						dp[pos+1][ns][nm][first] += cur
					}
				}
			}
		}
	}

	var ans int64
	// close the cycle: check substring crossing boundary
	for state := 0; state <= m; state++ {
		for matched := 0; matched <= 1; matched++ {
			for first := 0; first <= 1; first++ {
				cur := dp[n][state][matched][first]
				if cur == 0 {
					continue
				}
				if matched == 1 {
					ans += cur
					continue
				}
				// simulate feeding first bit once more
				ns := nxt[state][first]
				if ns == m {
					ans += cur
				}
			}
		}
	}

	fmt.Println(ans)
}

