func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	var s string
	fmt.Fscan(in, &s)
	m := len(s)

	// Build KMP automaton for pattern s
	pi := make([]int, m)
	for i := 1; i < m; i++ {
		j := pi[i-1]
		for j > 0 && s[i] != s[j] {
			j = pi[j-1]
		}
		if s[i] == s[j] {
			j++
		}
		pi[i] = j
	}
	next := make([][2]int, m+1)
	for state := 0; state <= m; state++ {
		for b := 0; b < 2; b++ {
			if state == m {
				next[state][b] = m
				continue
			}
			c := byte('0' + b)
			j := state
			for j > 0 && s[j] != c {
				j = pi[j-1]
			}
			if s[j] == c {
				j++
			}
			if j == m {
				next[state][b] = m
			} else {
				next[state][b] = j
			}
		}
	}

	// DP: dp[pos][state][mask] where mask is bitset of states visited so far
	// mask size m+1 -> up to 41 bits, fits in uint64
	dp := make([][][]uint64, n+1)
	for i := 0; i <= n; i++ {
		dp[i] = make([][]uint64, m+1)
		for st := 0; st <= m; st++ {
			dp[i][st] = make([]uint64, 1<<(0)) // placeholder, we'll use map-like via slice resizing
		}
	}
	// Instead of 3D slice with huge mask dimension, use map per (pos,state)
	type entry struct {
		state int
		mask  uint64
	}
	dpMap := make([]map[uint64]uint64, (n+1)*(m+1))
	idx := func(pos, st int) int { return pos*(m+1) + st }
	for i := range dpMap {
		dpMap[i] = make(map[uint64]uint64)
	}

	startMask := uint64(1 << 0)
	dpMap[idx(0, 0)][startMask] = 1

	for pos := 0; pos < n; pos++ {
		for st := 0; st <= m; st++ {
			cur := dpMap[idx(pos, st)]
			if len(cur) == 0 {
				continue
			}
			for mask, cnt := range cur {
				for b := 0; b < 2; b++ {
					nst := next[st][b]
					nmask := mask | (1 << uint(nst))
					dpMap[idx(pos+1, nst)][nmask] += cnt
				}
			}
		}
	}

	var ans uint64
	for st := 0; st <= m; st++ {
		cur := dpMap[idx(n, st)]
		for mask, cnt := range cur {
			if (mask & (1 << uint(m))) != 0 {
				ans += cnt
			}
		}
	}

	fmt.Println(ans)
}

