	for state := 0; state <= m; state++ {
		for c := 0; c < 2; c++ {
			if state == m {
				next[state][c] = m
				continue
			}
			ch := byte('0' + c)
			j := state
			for j > 0 && s[j] != ch {
				j = pi[j-1]
			}
			if j < m && s[j] == ch {
				j++
			}
			if j == m {
				next[state][c] = m
			} else {
				next[state][c] = j
			}
		}
	}

	// DP over positions, automaton state, first bit, last bit, found flag
	// dp[pos][state][fb][lb][found]
	dp := make([][][][][]int64, n+1)
	for i := 0; i <= n; i++ {
		dp[i] = make([][][][]int64, m+1)
		for st := 0; st <= m; st++ {
			dp[i][st] = make([][][]int64, 2)
			for fb := 0; fb < 2; fb++ {
				dp[i][st][fb] = make([][]int64, 2)
				for lb := 0; lb < 2; lb++ {
					dp[i][st][fb][lb] = make([]int64, 2)
				}
			}
		}
	}

	// Initialize position 1
	for b := 0; b < 2; b++ {
		st := next[0][b]
		found := 0
		if st == m {
			found = 1
		}
		dp[1][st][b][b][found]++
	}

	// Transition for positions 2..n
	for pos := 1; pos < n; pos++ {
		for st := 0; st <= m; st++ {
			for fb := 0; fb < 2; fb++ {
				for lb := 0; lb < 2; lb++ {
					for f := 0; f < 2; f++ {
						cur := dp[pos][st][fb][lb][f]
						if cur == 0 {
							continue
						}
						for b := 0; b < 2; b++ {
							nst := next[st][b]
							nf := f
							if nst == m {
								nf = 1
							}
							dp[pos+1][nst][fb][b][nf] += cur
						}
					}
				}
			}
		}
	}

	var ans int64 = 0

	// Count strings where s appears in linear part
	for st := 0; st <= m; st++ {
		for fb := 0; fb < 2; fb++ {
			for lb := 0; lb < 2; lb++ {
				ans += dp[n][st][fb][lb][1]
			}
		}
	}

	// Handle wrap-around occurrences when s is not found linearly
	// Only possible if m > 1
	if m > 1 {
		for st := 0; st <= m; st++ {
			for fb := 0; fb < 2; fb++ {
				for lb := 0; lb < 2; lb++ {
					cnt := dp[n][st][fb][lb][0]
					if cnt == 0 {
						continue
					}
