					cur := st
					found := false
					for k := 0; k < m-1; k++ {
						b := fb
						cur = next[cur][b]
						if cur == m {
							found = true
							break
						}
					}
					if found {
						ans += cnt
					}
				}
			}
		}
	}

	fmt.Println(ans)
}

