			c := byte('0' + b)
			j := state
			for j > 0 && s[j] != c {
				j = pi[j-1]
			}
			if j < m && s[j] == c {
				j++
			}
			next[state][b] = j
		}
	}

	// DP[pos][state][mask] where mask is bitset of visited states (0..m)
	// mask fits in uint64 since m<=40
	type key struct {
		pos   int
		state int
		mask  uint64
	}
	dp := make(map[key]uint64)
	var dfs func(pos, state int, mask uint64) uint64
	dfs = func(pos, state int, mask uint64) uint64 {
		if pos == n {
			// check if any rotation has substring s
			// i.e., some state m is visited
			if (mask & (1 << uint(m))) != 0 {
				return 1
			}
			return 0
		}
		k := key{pos, state, mask}
		if v, ok := dp[k]; ok {
			return v
		}
		var res uint64
		for b := 0; b < 2; b++ {
			ns := next[state][b]
			nmask := mask | (1 << uint(ns))
			res += dfs(pos+1, ns, nmask)
		}
		dp[k] = res
		return res
	}

	// initial state 0, mask with state 0 visited
	ans := dfs(0, 0, 1<<0)
	fmt.Println(ans)
}
